def db_data(_app: str, _query: str, insert_data: list[dict] | None = None) -> dict | list[tuple]:
    try:
        if not insert_data:
            result = execute_query(
                _query,
                params.get(_app)
            )
        else:
            result = execute_query(
                _query,
                params.get(_app),
                insert_data
            )
        return result

    except Exception as e:
        print(e)
        return {}


